from decimal import Decimal
from typing import Any


_ZERO = Decimal("0")
_EIGHT_TENTHS = Decimal("0.8")


def _as_decimal(value: Any) -> Decimal:
    """Apply legacy NVL-to-zero behavior and preserve decimal boundaries."""
    if value is None:
        return _ZERO
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return _ZERO
        return Decimal(value)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _account_sort_key(item: tuple[int, dict]) -> tuple:
    """Provide primary-key ordering for normal homogeneous CRM key types."""
    _, account = item
    value = account.get("ACCT_ID")

    if isinstance(value, Decimal):
        return (0, value)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return (0, Decimal(str(value)))
    if isinstance(value, str):
        return (1, value)
    if value is None:
        return (2, "")
    return (3, type(value).__name__, repr(value))


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[Any, Any]] = []

    exposure_by_account: dict[Any, Decimal] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") != "I":
            continue

        account_id = order.get("ACCT_ID")
        exposure_by_account[account_id] = (
            exposure_by_account.get(account_id, _ZERO)
            + _as_decimal(order.get("TOT_AMT"))
        )

    eligible = [
        (index, account)
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]

    for index, account in sorted(eligible, key=_account_sort_key):
        account_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(account_id, _ZERO)
        credit_limit = _as_decimal(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if (
            exposure <= credit_limit * _EIGHT_TENTHS
            and account.get("CRED_HOLD") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

        new_accounts[index] = account

    return new_accounts, audits
